exercise.solution:
import time

def medir_tiempo(func):
    def wrapper():
        inicio = time.time()
        func()
        fin = time.time()
        print(f'Tiempo: {fin - inicio} segundos')
    return wrapper

@medir_tiempo
def funcion_lenta():
    for i in range(1000000):
        pass

funcion_lenta()

